import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Safe Change and Recovery","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/safe-change-and-recovery.md","filePath":"architecture/safe-change-and-recovery.md","lastUpdated":null}'),o={name:"architecture/safe-change-and-recovery.md"};function r(s,e,c,d,l,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="safe-change-and-recovery" tabindex="-1">Safe Change and Recovery <a class="header-anchor" href="#safe-change-and-recovery" aria-label="Permalink to &quot;Safe Change and Recovery&quot;">​</a></h1><p><strong>Status:</strong> Requirements approved; mechanics are under design<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Archie is built and improved by agents as well as humans. The architecture MUST make a change easy to locate, understand, test, audit, extend, and reverse without requiring its author to understand unrelated parts of the application.</p><p>Separation of concerns is therefore an operational safety boundary, not only a code-organisation preference.</p><h2 id="required-outcomes" tabindex="-1">Required outcomes <a class="header-anchor" href="#required-outcomes" aria-label="Permalink to &quot;Required outcomes&quot;">​</a></h2><ul><li>An agent can improve a focused feature without receiving authority over unrelated domains.</li><li>Every event, function, action, setting, and policy has an identifiable owner and provenance.</li><li>Source and runtime changes pass deterministic checks outside the actor making the change.</li><li>A rejected or unhealthy candidate cannot replace the last known working version.</li><li>Invalid user configuration does not terminate an otherwise healthy application.</li><li>Configuration and service failures are observable, attributed, and eligible for bounded remediation or rollback.</li><li>The application continues serving unaffected capabilities when one capability is misconfigured or unhealthy.</li><li>Recovery failure is reported and contained rather than hidden in an unbounded retry loop.</li></ul><h2 id="source-changes" tabindex="-1">Source changes <a class="header-anchor" href="#source-changes" aria-label="Permalink to &quot;Source changes&quot;">​</a></h2><p>Agent-authored source changes occur through the task-execution boundary in an isolated workspace. The agent does not directly mutate the running installation.</p><p>Promotion is controlled by deterministic repository-owned policy, including tests, generated-reference drift checks, protected paths, change scope, and other required gates. The actor proposing a change cannot waive these checks.</p><p>Repository and domain separation SHOULD allow a task to load and modify only the governing requirements and code for its declared scope.</p><h2 id="runtime-changes" tabindex="-1">Runtime changes <a class="header-anchor" href="#runtime-changes" aria-label="Permalink to &quot;Runtime changes&quot;">​</a></h2><p>Configuration and other runtime changes are proposed as candidates rather than mutating the active state in place.</p><p>The affected domain owns:</p><ul><li>the command describing the semantic change;</li><li>validation of its typed settings;</li><li>health signals that demonstrate correct operation;</li><li>domain-specific remediation and rollback consequences.</li></ul><p>Shared policy supplies consistent evaluation, evidence, and audit mechanics. Identity supplies actor attribution. Infrastructure supplies external configuration storage, service control, and other operational adapters.</p><h2 id="runtime-change-protocol" tabindex="-1">Runtime change protocol <a class="header-anchor" href="#runtime-change-protocol" aria-label="Permalink to &quot;Runtime change protocol&quot;">​</a></h2><p>Last-known-good preservation and candidate promotion are the universal runtime change protocol.</p><ol><li>An identity proposes an immutable candidate version.</li><li>Infrastructure parses it without changing active state.</li><li>Each affected domain validates its typed settings.</li><li>Shared policy evaluates cross-cutting constraints.</li><li>Each affected capability prepares the candidate without destroying its active instance.</li><li>Capability-specific health checks prove the candidate works.</li><li>Runtime supervision atomically promotes the candidate.</li><li>A bounded observation period watches for delayed failure.</li><li>Failure restores the last-known-good version and records the reason, evidence, actor, and involved versions.</li><li>Repeated remediation failure stops retrying, isolates the capability, and reports the fault.</li></ol><p>The affected domain owns the semantic change command, typed validation, health signals, and remediation consequences. Shared runtime supervision owns the promotion transaction. Infrastructure performs storage and service-control operations.</p><p>The protocol&#39;s exact Go contracts, storage model, atomicity boundary, and observation rules require a focused runtime-supervision design pass.</p><h2 id="failure-isolation" tabindex="-1">Failure isolation <a class="header-anchor" href="#failure-isolation" aria-label="Permalink to &quot;Failure isolation&quot;">​</a></h2><p>Invalid input MUST leave the active valid configuration unchanged and produce a diagnostic record.</p><p>A capability that cannot start or reload SHOULD fail independently where its absence does not violate a declared application invariant. Unaffected capabilities continue operating.</p><p>Remediation MUST be bounded, observable, and policy-driven. Recovery MUST NOT silently oscillate between versions or retry forever.</p>',25)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
